def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    seen = set()

    for r in range(h):
        for c in range(w):
            if grid[r][c] == 8 or (r, c) in seen:
                continue

            stack = [(r, c)]
            seen.add((r, c))
            comp = []
            while stack:
                y, x = stack.pop()
                comp.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if (0 <= ny < h and 0 <= nx < w and
                            grid[ny][nx] != 8 and (ny, nx) not in seen):
                        seen.add((ny, nx))
                        stack.append((ny, nx))

            colors = {grid[y][x] for y, x in comp if grid[y][x] != 0}
            if len(colors) != 1:
                continue
            color = next(iter(colors))
            cr = [y for y, x in comp if grid[y][x] == color]
            cc = [x for y, x in comp if grid[y][x] == color]
            top, bottom = min(y for y, x in comp), max(y for y, x in comp)
            left, right = min(x for y, x in comp), max(x for y, x in comp)
            pt, pl = min(cr), min(cc)
            ph, pw = max(cr) - pt + 1, max(cc) - pl + 1

            pattern = [
                [grid[pt + i][pl + j] for j in range(pw)]
                for i in range(ph)
            ]
            for y, x in comp:
                out[y][x] = pattern[(y - pt) % ph][(x - pl) % pw]

    return out
